sys_script.script:
(function executeRule(current, previous /*null when async*/) {

	// =========================================
// 1. MIM DECLARATION VALIDATION
// =========================================

// Validate only when state is Accepted
var currentState = current.getValue('state');

if (currentState != 'accepted') {
return;
}

// =========================================
// 2. REQUIRED FIELD VALIDATION
// =========================================

var errors = [];

var requiredFields = [
{
name: 'short_description',
label: 'Short Description'
},
{
name: 'description',
label: 'Description'
},
{
name: 'business_service',
label: 'Business Service'
},
{
name: 'major_incident_manager',
label: 'Major Incident Manager'
},
{
name: 'assignment_group',
label: 'Assignment Group'
},
{
name: 'impact',
label: 'Impact'
},
{
name: 'urgency',
label: 'Urgency'
}
];

// Check all mandatory fields
for (var i = 0; i < requiredFields.length; i++) {

var field = requiredFields[i];

if (!current.isValidField(field.name)) {

errors.push(
'Invalid field configuration: ' + field.label
);

} else if (gs.nil(current.getValue(field.name))) {

errors.push(
field.label + ' is mandatory.'
);
}
}

// =========================================
// 3. PRIORITY VALIDATION
// =========================================

if (current.isValidField('priority')) {

var priority = current.getValue('priority');

if (priority != '1' && priority != '2') {

errors.push(
'Only P1 or P2 incidents can be accepted as Major Incidents.'
);
}
}

// =========================================
// 4. IMPACT AND URGENCY VALIDATION
// =========================================

var impact = current.getValue('impact');
var urgency = current.getValue('urgency');

if (impact == '3' && urgency == '3') {

errors.push(
'Low impact and low urgency cannot be accepted as a Major Incident.'
);
}

// =========================================
// 5. ABORT IF VALIDATION FAILS
// =========================================

if (errors.length > 0) {

for (var j = 0; j < errors.length; j++) {

gs.addErrorMessage(errors[j]);

}

gs.addErrorMessage(
'Major Incident declaration failed. ' +
'Please correct the information and try again.'
);

current.setAbortAction(true);

return;
}

// =========================================
// 6. SUCCESS MESSAGE
// =========================================

gs.addInfoMessage(
'Major Incident accepted successfully. ' +
'All declaration validations passed.'
);


})(current, previous);
